 * Chorobates, connector, 2026-09-11.
 *
 * Testing one row of the Gilbreath dictionary. Odlyzko's reduction of
 * Gilbreath's conjecture works like this: the entries of the difference
 * triangle eventually lie in {0, 2}, that set is CLOSED under the rule
 * a(i+1,j) = |a(i,j) - a(i,j+1)|, and a leading 1 with n such entries to its
 * right keeps the left column at 1 for n more rows -- a finite window of a
 * closed sub-alphabet SHIELDS the boundary column, losing one cell per row.
 *
 * The board's `column_alternating_shrink` is the same shape for rule 30: an
 * alternating block of depth L left of the origin gives depth L-1 at the next
 * row, and holds the centre column black for L rows. So the question this
 * script asks is whether the alternating block is the SMALLEST member of a
 * family of rule 30 shields (as {0,2} is one of many sub-alphabets over there)
 * or the ONLY one.
 *
 * Three measurements:
 *
 *  (A) the one-sided shield: at every row t, the maximal depth of alternation
 *      running leftward from the origin, cross-checked against the current
 *      black run of the centre column (they must be equal, by the board's
 *      `column_alternating_of_black_run` and `column_black_run_of_alternating`).
 *
 *  (B) the two-sided shield: at every row t, the longest window AROUND the
 *      origin that is spatially p-periodic for some p <= PMAX with the induced
 *      p-ring temporally periodic under rule 30. Such a window is a patch of a
 *      genuine space-time periodic rule 30 picture, so it determines the centre
 *      column for min(left extent, right extent) rows by the cone alone -- the
 *      exact analogue of Odlyzko's window. Question: does it ever beat (A)?
 *
 *  (C) exhaustive: over ALL 2^L words on cells 0, -1, ..., -(L-1), which ones
 *      force the centre column for more than one row against every completion
 *      of the rest of the row? Tested against random completions. If the
 *      alternating word is alone here, rule 30 has exactly one one-sided
 *      shield and the family does not exist.
 */

const T = 20000;          // rows for (A) and (B)
const PMAX = 14;          // ring widths for (B)
const LMAX = 14;          // window depth for (C)

// ---------------------------------------------------------------- the picture
// cell(t, x) = row[x + OFF]. The cone is -t .. t, so OFF = T + 2 is enough.
const OFF = T + 2;
const W = 2 * T + 5;
let row = new Uint8Array(W);
let next = new Uint8Array(W);
row[OFF] = 1;

// ------------------------------------------------- (B) which p-rings are cyclic
// A ring of width p is the configuration repeat(w). It is temporally periodic
// iff its state lies on a cycle of the ring map. Collect those states.
function ringStep(state, p) {
  let out = 0;
  for (let i = 0; i < p; i++) {
    const l = (state >> ((i + p - 1) % p)) & 1;
    const c = (state >> i) & 1;
    const r = (state >> ((i + 1) % p)) & 1;
    if (l ^ (c | r)) out |= 1 << i;
  }
  return out;
}
const cyclic = [];   // cyclic[p] = Uint8Array over 2^p, 1 if on a cycle
for (let p = 1; p <= PMAX; p++) {
  const n = 1 << p;
  const nextOf = new Int32Array(n);
  for (let s = 0; s < n; s++) nextOf[s] = ringStep(s, p);
  // a state is on a cycle iff iterating n times from it returns to it
  const mark = new Uint8Array(n);
  const colour = new Int32Array(n).fill(-1);
  for (let s = 0; s < n; s++) {
    if (colour[s] !== -1) continue;
    const path = [];
    let x = s;
    while (colour[x] === -1) { colour[x] = s; path.push(x); x = nextOf[x]; }
    if (colour[x] === s) {                       // found a fresh cycle
      let y = x;
      do { mark[y] = 1; y = nextOf[y]; } while (y !== x);
    }
    for (const z of path) colour[z] = -2;        // done, but keep !== -1
    colour[s] = -2;
  }
  cyclic[p] = mark;
}
{
  const counts = [];
  for (let p = 1; p <= PMAX; p++) {
    let c = 0;
    for (let s = 0; s < (1 << p); s++) if (cyclic[p][s]) c++;
    counts.push(`${p}:${c}`);
  }
  console.log('cyclic ring states per width  ' + counts.join(' '));
}

// --------------------------------------------------------------------- sweep
let bestAlt = 0, bestAltT = -1;
let bestTwo = 0, bestTwoT = -1, bestTwoP = -1;
let twoBeatsAlt = 0;
const altHist = new Map();
let runStart = 0, runColour = 1, runMismatch = 0, runsChecked = 0;

for (let t = 0; t <= T; t++) {
  // (A) alternating depth leftward from the origin
  let alt = 0;
  while (alt <= t && row[OFF - alt] === (alt % 2 === 0 ? 1 : 0)) alt++;
  // only meaningful when the centre is black; a white centre gives alt = 0
  if (row[OFF] === 1) {
    if (alt > bestAlt) { bestAlt = alt; bestAltT = t; }
    altHist.set(alt, (altHist.get(alt) ?? 0) + 1);
  }

  // (A') cross-check: alt should equal the black run of the centre column
  // starting at t. Checked below in the run pass (needs future rows), so here
  // just record the row's alt into an array for rows that start a run.
  altAt[t] = row[OFF] === 1 ? alt : 0;
  centre[t] = row[OFF];

  // (B) best two-sided periodic patch around the origin
  let two = 0, twoP = -1;
  for (let p = 1; p <= PMAX; p++) {
    // extend left and right from the origin while the row is p-periodic
    let a = 0;
    while (a < t && row[OFF - a - 1] === row[OFF - ((a + 1) % p) - p * Math.floor(((a + 1) % p === 0 ? 1 : 0))]) break;
    // simpler and exact: compare to the p-window at the origin
    a = 0;
    while (a + 1 <= t && row[OFF - (a + 1)] === row[OFF - ((a + 1) % p)]) a++;
    let b = 0;
    while (b + 1 <= t && row[OFF + (b + 1)] === row[OFF + ((b + 1) % p)]) b++;
    if (a < p - 1 || b < p - 1) { /* window shorter than one period: still fine */ }
    // the induced ring state, read from cells 0 .. p-1 of the window
    let st = 0;
    for (let i = 0; i < p; i++) if (row[OFF + i] === 1) st |= 1 << i;
    if (b < p - 1) continue;                      // not enough cells to read the ring
    if (!cyclic[p][st]) continue;                 // not a temporally periodic ring
    const shield = Math.min(a, b);
    if (shield > two) { two = shield; twoP = p; }
  }
  if (two > bestTwo) { bestTwo = two; bestTwoT = t; bestTwoP = twoP; }
  if (row[OFF] === 1 && two > alt) twoBeatsAlt++;

  // step
  for (let x = 1; x < W - 1; x++) next[x] = row[x - 1] ^ (row[x] | row[x + 1]);
  const tmp = row; row = next; next = tmp;
}

console.log(`(A) longest one-sided alternating block, rows 0..${T}: ${bestAlt} at t=${bestAltT}`);
console.log(`(B) longest two-sided cyclic-ring patch around the origin: ${bestTwo} at t=${bestTwoT}, p=${bestTwoP}`);
console.log(`(B) rows where the two-sided patch beat the alternating block: ${twoBeatsAlt} of ${T + 1}`);

// (A') the cross-check, now that the whole centre column is in hand
let mism = 0, checked = 0;
for (let t = 0; t <= T; t++) {
  if (centre[t] !== 1) continue;
  if (t > 0 && centre[t - 1] === 1) continue;     // only run starts
  let L = 0;
  while (t + L <= T && centre[t + L] === 1) L++;
  checked++;
  if (altAt[t] !== L) mism++;
}
console.log(`(A') maximal black runs checked: ${checked}, alt-depth != run-length: ${mism}`);

// ------------------------------------------------------------------ (C) forcing
// Over all 2^L words on cells 0, -1, ..., -(L-1): how many rows of the centre
// column do they force, against random completions of the rest of the row?
function forcingDepth(word, L, samples, rng) {
  // positions -(L-1)..0 fixed by `word` (bit j = cell -j); everything else free
  const M = L + 6;                                 // free margin each side
  const lo = -(L - 1) - M, hi = M;
  const n = hi - lo + 1;
  const off = -lo;
  let seen = null;
  for (let s = 0; s < samples; s++) {
    let r = new Uint8Array(n + 2 * L + 4);
    let nx = new Uint8Array(n + 2 * L + 4);
    const base = L + 2;
    for (let i = 0; i < n; i++) r[base + i] = rng() & 1;
    for (let j = 0; j < L; j++) r[base + off - j] = (word >> j) & 1;
    const col = [];
    for (let k = 0; k < L; k++) {
      col.push(r[base + off]);
      for (let x = 1; x < r.length - 1; x++) nx[x] = r[x - 1] ^ (r[x] | r[x + 1]);
      const tmp = r; r = nx; nx = tmp;
      // cells within k+1 of the free margin are contaminated; the shield claim
      // only concerns the origin, whose cone reaches out to +-(k+1) <= M.
    }
    if (seen === null) { seen = col; continue; }
    for (let k = 0; k < L; k++) if (col[k] !== seen[k]) return k;   // first divergence
  }
  return L;
}

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0);
  };
}

console.log('');
console.log('(C) one-sided shields: words on cells 0..-(L-1) and how many rows of');
console.log('    the centre column they force against 300 random completions.');
for (let L = 2; L <= LMAX; L++) {
  const rng = mulberry32(12345 + L);
  let best = 0; const winners = [];
  for (let w = 0; w < (1 << L); w++) {
    const d = forcingDepth(w, L, 300, rng);
